interface DataSource { fun read(): String }

class FileSource : DataSource {
    override fun read() = "raw data"
}

class EncryptedSource(private val inner: DataSource) : DataSource {
    override fun read() = decrypt(inner.read())
}

class CachedSource(private val inner: DataSource) : DataSource {
    private var cache: String? = null
    override fun read() = cache ?: inner.read().also { cache = it }
}

val source = CachedSource(EncryptedSource(FileSource()))
